1	/**
2	 * #{#sec1b} Signed URL Utility
3	 *
4	 * Centralizes signed URL generation for the receipts storage bucket.
5	 * Replaces all getPublicUrl() calls with time-limited signed URLs.
6	 */
7	
8	import { supabase } from '$lib/supabaseClient';
9	
10	/** Default signed URL expiry: 1 hour */
11	const DEFAULT_EXPIRY_SECONDS = 3600;
12	
13	/**
14	 * Generate a signed URL for a file in the receipts storage bucket.
15	 *
16	 * @param path - Storage path (e.g. "user-id/filename.jpg")
17	 * @param expiresIn - URL lifetime in seconds (default: 3600)
18	 * @returns Signed URL string, or null if path is empty or generation fails
19	 */
20	export async function getSignedReceiptUrl(
21		path: string | null | undefined,
22		expiresIn: number = DEFAULT_EXPIRY_SECONDS
23	): Promise<string | null> {
24		if (!path) return null;
25	
26		const { data, error } = await supabase.storage.from('receipts').createSignedUrl(path, expiresIn);
27	
28		if (error) {
29			console.error('Failed to create signed URL for path:', path, 'error:', error.message);
30			return null;
31		}
32	
33		return data.signedUrl;
34	}
