1	<script lang="ts">
2		import { onMount } from 'svelte';
3		import { page } from '$app/stores';
4		import { goto } from '$app/navigation';
5		import { supabase } from '$lib/supabaseClient';
6		import { TransactionService } from '$lib/services/TransactionService';
7		import {
8			CREDIT_CARD_TYPES,
9			type CreditCardType,
10			type TransactionRow
11		} from '$lib/models/Transaction';
12		import { getValidDate } from '$lib/utils/dateValidation';
13		import { Datepicker } from 'flowbite-svelte';
14		import { toDate, toISODateString } from '$lib/utils/dateConversion';
15		import { formatBulkDeleteMessage } from '$lib/utils/formatBulkDeleteMessage';
16	
17		let allTransactions: TransactionRow[] = $state([]);
18		let familyId: string | null = $state(null);
19		let sort: 'transaction_date' | 'vendor_name' | 'amount' | 'credit_card_type' = $state('transaction_date');
20		let direction: 'asc' | 'desc' = $state('desc');
21		let error: string | null = $state(null);
22		let importing = $state(false);
23		let selectedCardType: CreditCardType = $state('PC Financial');
24		let filterCardType: CreditCardType | 'all' = $state('all');
25		let includeIgnored = $state(false);
26		let editRow: TransactionRow | null = $state(null);
27		let deleting = $state(new Set<string>());
28		let bulkDeleting = $state(false);
29		let successMessage: string | null = $state(null);
30	
31		// #{#sdf2c} Read date filters from URL query parameters
32		let urlDateFrom = $derived(getValidDate($page.url.searchParams.get('dateFrom')));
33		let urlDateTo = $derived(getValidDate($page.url.searchParams.get('dateTo')));
34	
35		// Client-side filters - temporary values for inputs
36		let tempFilterDateFrom = $state(urlDateFrom);
37		let tempFilterDateTo = $state(urlDateTo);
38		let tempFilterVendor = $state('');
39		let tempFilterAmountMin = $state('');
40		let tempFilterAmountMax = $state('');
41		let tempFilterCreditCardType: CreditCardType | 'all' = $state('all'); // #{#tcf1a}
42	
43		// Sync temp date values when URL changes
44		$effect(() => {
45			tempFilterDateFrom = urlDateFrom;
46			tempFilterDateTo = urlDateTo;
47		});
48	
49		// Active filter values used for filtering (non-date filters only)
50		let filterVendor = $state('');
51		let filterAmountMin = $state('');
52		let filterAmountMax = $state('');
53		let filterCreditCardType: CreditCardType | 'all' = $state('all'); // #{#tcf1a}
54	
55		async function loadTransactions(): Promise<void> {
56			if (!familyId) return;
57			error = null;
58			try {
59				const options: any = {
60					sort,
61					direction,
62					includeIgnored
63				};
64				if (filterCardType !== 'all') {
65					options.creditCardType = filterCardType;
66				}
67				allTransactions = await TransactionService.get().list(familyId, options);
68			} catch (e: any) {
69				error = e?.message ?? 'Failed to load transactions';
70			}
71		}
72	
73		async function getDefaultFamily(): Promise<string | null> {
74			const { data: familyMembers } = await supabase
75				.from('family_members')
76				.select('family_id, is_default')
77				.eq('user_id', (await supabase.auth.getUser()).data.user?.id)
78				.order('is_default', { ascending: false })
79				.limit(1);
80	
81			return familyMembers?.[0]?.family_id || null;
82		}
83	
84		onMount(async () => {
85			familyId = await getDefaultFamily();
86			if (familyId) {
87				await loadTransactions();
88			} else {
89				error = 'No family found. Please create or join a family first.';
90			}
91		});
92	
93		function sortBy(field: typeof sort): void {
94			if (sort === field) direction = direction === 'asc' ? 'desc' : 'asc';
95			else {
96				sort = field;
97				direction = 'asc';
98			}
99			loadTransactions();
100		}
101	
102		async function onFileSelected(e: Event): Promise<void> {
103			const input = e.target as HTMLInputElement;
104			const file = input.files?.[0];
105			if (!file || !familyId) return;
106	
107			importing = true;
108			error = null;
109			successMessage = null;
110	
111			try {
112				const result = await TransactionService.get().importFromCSV(familyId, file, selectedCardType);
113	
114				if (result.errors.length > 0) {
115					error = result.errors.join('\n');
116				}
117	
118				if (result.imported > 0 || result.skipped > 0) {
119					// #{#tid3a} Import summary UX
120					if (result.imported === 0 && result.skipped > 0) {
121						successMessage = `No new transactions — ${result.skipped} already in your records`;
122					} else if (result.skipped > 0) {
123						successMessage = `Imported ${result.imported} transaction${result.imported === 1 ? '' : 's'}, skipped ${result.skipped} duplicate${result.skipped === 1 ? '' : 's'}`;
124					} else {
125						successMessage = `Imported ${result.imported} transaction${result.imported === 1 ? '' : 's'}`;
126					}
127					await loadTransactions();
128				}
129			} catch (e: any) {
130				error = e?.message ?? 'Failed to import transactions';
131			} finally {
132				importing = false;
133				input.value = '';
134			}
135		}
136	
137		async function deleteTransaction(t: TransactionRow): Promise<void> {
138			if (!confirm('Delete this transaction?')) return;
139			deleting.add(t.id);
140			deleting = new Set(deleting);
141			error = null;
142			try {
143				await TransactionService.get().delete(t.id);
144				allTransactions = allTransactions.filter((x) => x.id !== t.id);
145				successMessage = 'Transaction deleted';
146			} catch (e: any) {
147				error = e?.message ?? 'Failed to delete transaction';
148			} finally {
149				deleting.delete(t.id);
150				deleting = new Set(deleting);
151			}
152		}
153	
154		// #{#tbd1a} Bulk delete filtered transactions
155		async function deleteFiltered(): Promise<void> {
156			if (!familyId || transactions.length === 0) return;
157	
158			const filters: { creditCardType?: string; dateFrom?: string; dateTo?: string } = {};
159			if (filterCardType !== 'all') filters.creditCardType = filterCardType;
160			if (filterCreditCardType !== 'all') filters.creditCardType = filterCreditCardType;
161			if (urlDateFrom) filters.dateFrom = urlDateFrom;
162			if (urlDateTo) filters.dateTo = urlDateTo;
163	
164			const msg = formatBulkDeleteMessage(transactions.length, filters);
165			if (!confirm(msg)) return;
166	
167			bulkDeleting = true;
168			error = null;
169			try {
170				const options: any = {};
171				if (filters.creditCardType) options.creditCardType = filters.creditCardType;
172				if (urlDateFrom) options.afterDate = urlDateFrom;
173				if (urlDateTo) {
174					// Add one day to make dateTo inclusive (deleteAll uses < for beforeDate)
175					const toDateObj = new Date(urlDateTo + 'T12:00:00');
176					toDateObj.setDate(toDateObj.getDate() + 1);
177					options.beforeDate = toDateObj.toISOString().split('T')[0];
178				}
179	
180				const deleted = await TransactionService.get().deleteAll(familyId, options);
181				successMessage = `${deleted} transaction${deleted !== 1 ? 's' : ''} deleted`;
182				await loadTransactions();
183			} catch (e: any) {
184				error = e?.message ?? 'Failed to delete transactions';
185			} finally {
186				bulkDeleting = false;
187			}
188		}
189	
190		async function toggleExcluded(t: TransactionRow): Promise<void> {
191			error = null;
192			try {
193				const updated = await TransactionService.get().toggleExcluded(t.id, !t.excluded);
194				allTransactions = allTransactions.map((x) => (x.id === updated.id ? updated : x));
195				successMessage = updated.excluded ? 'Transaction excluded' : 'Transaction included';
196			} catch (e: any) {
197				error = e?.message ?? 'Failed to update transaction';
198			}
199		}
200	
201		async function saveEdit(): Promise<void> {
202			if (!editRow) return;
203			error = null;
204			try {
205				const updated = await TransactionService.get().update(editRow.id, {
206					vendor_name: editRow.vendor_name,
207					amount: editRow.amount,
208					transaction_date: editRow.transaction_date,
209					credit_card_type: editRow.credit_card_type
210				});
211				allTransactions = allTransactions.map((t) => (t.id === updated.id ? updated : t));
212				editRow = null;
213				successMessage = 'Transaction updated';
214			} catch (e: any) {
215				error = e?.message ?? 'Failed to save transaction';
216			}
217		}
218	
219		function formatAmount(amount: number): string {
220			const abs = Math.abs(amount);
221			const formatted = abs.toFixed(2);
222			return amount < 0 ? `-$${formatted}` : `$${formatted}`;
223		}
224	
225		function getAmountClass(amount: number): string {
226			return amount < 0 ? 'text-red-600' : 'text-green-600';
227		}
228	
229		function applyClientFilters(txns: TransactionRow[]): TransactionRow[] {
230			return txns.filter((t) => {
231				// #{#sdf1b} Filter by date range using URL parameters
232				if (urlDateFrom && t.transaction_date < urlDateFrom) return false;
233				if (urlDateTo && t.transaction_date > urlDateTo) return false;
234	
235				// Filter by vendor name (local state)
236				if (filterVendor) {
237					const vendorSearch = filterVendor.toLowerCase();
238					const vendor = t.vendor_name.toLowerCase();
239					if (!vendor.includes(vendorSearch)) return false;
240				}
241	
242				// Filter by amount range (local state)
243				if (filterAmountMin) {
244					const minAmount = parseFloat(filterAmountMin);
245					if (!isNaN(minAmount) && Math.abs(t.amount) < minAmount) return false;
246				}
247				if (filterAmountMax) {
248					const maxAmount = parseFloat(filterAmountMax);
249					if (!isNaN(maxAmount) && Math.abs(t.amount) > maxAmount) return false;
250				}
251	
252				// #{#tcf1a} Filter by credit/bank type (local state)
253				if (filterCreditCardType !== 'all') {
254					if (t.credit_card_type !== filterCreditCardType) return false;
255				}
256	
257				return true;
258			});
259		}
260	
261		function applyFilterValues(): void {
262			// #{#sdf2c} Update URL with date filters
263			const params = new URLSearchParams($page.url.searchParams);
264	
265			if (tempFilterDateFrom) params.set('dateFrom', tempFilterDateFrom);
266			else params.delete('dateFrom');
267	
268			if (tempFilterDateTo) params.set('dateTo', tempFilterDateTo);
269			else params.delete('dateTo');
270	
271			goto(`${$page.url.pathname}?${params.toString()}`, { replaceState: true, keepFocus: true });
272	
273			// Apply non-date filters locally
274			filterVendor = tempFilterVendor;
275			filterAmountMin = tempFilterAmountMin;
276			filterAmountMax = tempFilterAmountMax;
277			filterCreditCardType = tempFilterCreditCardType; // #{#tcf1a}
278		}
279	
280		function clearClientFilters(): void {
281			// #{#sdf2c} Clear URL date filters
282			const params = new URLSearchParams($page.url.searchParams);
283			params.delete('dateFrom');
284			params.delete('dateTo');
285			goto(`${$page.url.pathname}?${params.toString()}`, { replaceState: true, keepFocus: true });
286	
287			// Clear local filters
288			tempFilterVendor = '';
289			tempFilterAmountMin = '';
290			tempFilterAmountMax = '';
291			tempFilterCreditCardType = 'all'; // #{#tcf1a}
292			filterVendor = '';
293			filterAmountMin = '';
294			filterAmountMax = '';
295			filterCreditCardType = 'all'; // #{#tcf1a}
296		}
297	
298		$effect(() => {
299			filterCardType;
300			includeIgnored;
301			loadTransactions();
302		});
303	
304		let transactions = $derived(applyClientFilters(allTransactions));
305	
306		let hasActiveFilters = $derived(
307			urlDateFrom || urlDateTo || filterVendor || filterAmountMin || filterAmountMax || filterCreditCardType !== 'all' // #{#tcf2a}
308		);
309	</script>
310	
311	<svelte:head>
312		<title>Credit Card & Bank Transactions</title>
313	</svelte:head>
314	
315	<div class="mb-6">
316		<h1 class="mb-2 text-2xl font-bold">Credit Card & Bank Transactions</h1>
317		<p class="text-gray-600">
318			Import and manage transactions from your credit cards and bank accounts.
319		</p>
320	</div>
321	
322	{#if error}
323		<div class="mb-4 rounded border border-red-200 bg-red-50 p-3 whitespace-pre-wrap text-red-700">
324			{error}
325			<button class="ml-2 underline" onclick={() => (error = null)}>Dismiss</button>
326		</div>
327	{/if}
328	
329	{#if successMessage}
330		<div class="mb-4 rounded border border-green-200 bg-green-50 p-3 text-green-700">
331			{successMessage}
332			<button class="ml-2 underline" onclick={() => (successMessage = null)}>Dismiss</button>
333		</div>
334	{/if}
335	
336	<div class="mb-6 rounded border bg-white p-4 shadow-sm">
337		<h2 class="mb-3 font-semibold">Import Transactions</h2>
338		<div class="flex flex-col gap-3 sm:flex-row sm:items-end">
339			<div class="flex-1">
340				<label class="mb-1 block text-sm font-medium">Credit Card / Bank Type</label>
341				<select
342					bind:value={selectedCardType}
343					class="w-full rounded border border-gray-300 px-3 py-2"
344					disabled={importing}
345				>
346					{#each CREDIT_CARD_TYPES as cardType}
347						<option value={cardType}>{cardType}</option>
348					{/each}
349				</select>
350			</div>
351			<div class="flex-1">
352				<label
353					class="inline-flex w-full cursor-pointer items-center justify-center gap-2 rounded border bg-blue-600 px-4 py-2 text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
354				>
355					<input
356						type="file"
357						accept=".csv,.xls,.xlsx"
358						onchange={onFileSelected}
359						disabled={importing}
360						class="hidden"
361					/>
362					{importing ? 'Importing...' : 'Select CSV / Excel File'}
363				</label>
364			</div>
365		</div>
366		<p class="mt-2 text-xs text-gray-500">
367			Select the bank/card type that matches your file format, then choose the file to import. Supports CSV, XLS, and XLSX files.
368		</p>
369	</div>
370	
371	<!-- Filters -->
372	<div class="mb-4 rounded border bg-white p-4 shadow-sm">
373		<h2 class="mb-3 font-semibold">Filters</h2>
374		<div class="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-6">
375			<div>
376				<label class="mb-1 block text-sm font-medium">Date From</label>
377				<Datepicker
378					value={toDate(tempFilterDateFrom)}
379					onselect={(date) => { tempFilterDateFrom = toISODateString(date); }}
380					placeholder="From date"
381					inputmode="text"
382				/>
383			</div>
384			<div>
385				<label class="mb-1 block text-sm font-medium">Date To</label>
386				<Datepicker
387					value={toDate(tempFilterDateTo)}
388					onselect={(date) => { tempFilterDateTo = toISODateString(date); }}
389					placeholder="To date"
390					inputmode="text"
391				/>
392			</div>
393			<div>
394				<label class="mb-1 block text-sm font-medium">Vendor Name</label>
395				<input
396					type="text"
397					bind:value={tempFilterVendor}
398					class="w-full rounded border border-gray-300 px-3 py-2 text-sm"
399					placeholder="Search vendor..."
400				/>
401			</div>
402			<div>
403				<label class="mb-1 block text-sm font-medium">Min Amount ($)</label>
404				<input
405					type="number"
406					step="0.01"
407					bind:value={tempFilterAmountMin}
408					class="w-full rounded border border-gray-300 px-3 py-2 text-sm"
409					placeholder="Min"
410				/>
411			</div>
412			<div>
413				<label class="mb-1 block text-sm font-medium">Max Amount ($)</label>
414				<input
415					type="number"
416					step="0.01"
417					bind:value={tempFilterAmountMax}
418					class="w-full rounded border border-gray-300 px-3 py-2 text-sm"
419					placeholder="Max"
420				/>
421			</div>
422			<!-- #{#tcf1b} Credit/Bank Type Filter -->
423			<div>
424				<label class="mb-1 block text-sm font-medium">Card/Bank Type</label>
425				<select
426					bind:value={tempFilterCreditCardType}
427					class="w-full rounded border border-gray-300 px-3 py-2 text-sm"
428				>
429					<option value="all">All Types</option>
430					{#each CREDIT_CARD_TYPES as cardType}
431						<option value={cardType}>{cardType}</option>
432					{/each}
433				</select>
434			</div>
435		</div>
436		<div class="mt-3 flex items-center justify-between">
437			<div class="flex gap-2">
438				<button
439					onclick={applyFilterValues}
440					class="rounded bg-blue-600 px-4 py-2 text-sm text-white hover:bg-blue-700"
441				>
442					Apply Filters
443				</button>
444				<button
445					onclick={clearClientFilters}
446					class="rounded border border-gray-300 px-4 py-2 text-sm hover:bg-gray-50"
447				>
448					Clear Filters
449				</button>
450				<!-- #{#tbd1a} Bulk delete filtered transactions -->
451				{#if hasActiveFilters && transactions.length > 0}
452					<button
453						onclick={deleteFiltered}
454						disabled={bulkDeleting}
455						class="rounded bg-red-600 px-4 py-2 text-sm text-white hover:bg-red-700 disabled:opacity-50"
456					>
457						{bulkDeleting ? 'Deleting...' : `Delete Filtered (${transactions.length})`}
458					</button>
459				{/if}
460			</div>
461			{#if hasActiveFilters}
462				<span class="text-sm text-gray-600">
463					Showing {transactions.length} of {allTransactions.length} transactions
464				</span>
465			{/if}
466		</div>
467	</div>
468	
469	<div class="mb-4 flex items-center justify-between">
470		<div class="flex items-center gap-4">
471			<label class="flex items-center gap-2 text-sm">
472				<span class="font-medium">Card Type:</span>
473				<select bind:value={filterCardType} class="rounded border px-2 py-1">
474					<option value="all">All Types</option>
475					{#each CREDIT_CARD_TYPES as cardType}
476						<option value={cardType}>{cardType}</option>
477					{/each}
478				</select>
479			</label>
480			<label class="flex items-center gap-2 text-sm">
481				<input type="checkbox" bind:checked={includeIgnored} class="rounded" />
482				<span>Show excluded</span>
483			</label>
484		</div>
485		<div class="text-sm text-gray-600">
486			Total: {transactions.length} transaction{transactions.length !== 1 ? 's' : ''}
487		</div>
488	</div>
489	
490	<div class="overflow-x-auto rounded border bg-white shadow-sm">
491		<table class="min-w-full text-sm">
492			<thead class="bg-gray-50">
493				<tr>
494					<th class="cursor-pointer px-3 py-2 text-left" onclick={() => sortBy('transaction_date')}>
495						Date
496						{#if sort === 'transaction_date'}
497							<span class="text-xs">{direction === 'asc' ? '▲' : '▼'}</span>
498						{/if}
499					</th>
500					<th class="cursor-pointer px-3 py-2 text-left" onclick={() => sortBy('vendor_name')}>
501						Vendor
502						{#if sort === 'vendor_name'}
503							<span class="text-xs">{direction === 'asc' ? '▲' : '▼'}</span>
504						{/if}
505					</th>
506					<th class="cursor-pointer px-3 py-2 text-right" onclick={() => sortBy('amount')}>
507						Amount
508						{#if sort === 'amount'}
509							<span class="text-xs">{direction === 'asc' ? '▲' : '▼'}</span>
510						{/if}
511					</th>
512					<th class="cursor-pointer px-3 py-2 text-left" onclick={() => sortBy('credit_card_type')}>
513						Card/Bank Type
514						{#if sort === 'credit_card_type'}
515							<span class="text-xs">{direction === 'asc' ? '▲' : '▼'}</span>
516						{/if}
517					</th>
518					<th class="px-3 py-2 text-center">Actions</th>
519				</tr>
520			</thead>
521			<tbody>
522				{#if transactions.length === 0}
523					<tr>
524						<td colspan="5" class="px-3 py-8 text-center">
525							{#if allTransactions.length === 0}
526								<!-- #{#ems1a} No data empty state -->
527								<div class="flex flex-col items-center gap-3">
528									<svg class="h-12 w-12 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
529										<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
530											d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" />
531									</svg>
532									<h3 class="text-lg font-medium text-gray-700">No transactions yet</h3>
533									<p class="max-w-md text-sm text-gray-600">
534										Import your credit card or bank transactions from a CSV or Excel file to get started.
535										Select your bank type and upload your statement.
536									</p>
537								</div>
538							{:else}
