300		function applyClientFilters(rcts: ReceiptRow[]): ReceiptRow[] {
301			// #{#dup5a} Pre-compute duplicate IDs when filter is active
302			let dupeIds: Set<string> | null = null;
303			if (filterDuplicates) {
304				const dupes = detectDuplicates(rcts);
305				dupeIds = new Set<string>();
306				for (const ids of dupes.values()) {
307					for (const id of ids) dupeIds.add(id);
308				}
309			}
310	
311			return rcts.filter((r) => {
312				// #{#dtv3a} Filter by suspicious_date (Needs Review)
313				if (filterNeedsReview && !r.suspicious_date) return false;
314	
315				// #{#dup5a} Filter by duplicate status
316				if (filterDuplicates && dupeIds && !dupeIds.has(r.id)) return false;
317	
318				// #{#sdf1b} Filter by date range using URL parameters
319				if (urlDateFrom && r.transaction_date && r.transaction_date < urlDateFrom) return false;
320				if (urlDateTo && r.transaction_date && r.transaction_date > urlDateTo) return false;
321	
322				// Filter by merchant name (local state)
323				if (filterMerchant) {
324					const merchantSearch = filterMerchant.toLowerCase();
325					const merchant = (r.merchant_name || '').toLowerCase();
326					if (!merchant.includes(merchantSearch)) return false;
327				}
328	
329				// Filter by amount range (local state)
330				if (filterAmountMin && r.total_amount !== null) {
331					const minAmount = parseFloat(filterAmountMin);
332					if (!isNaN(minAmount) && r.total_amount < minAmount) return false;
333				}
334				if (filterAmountMax && r.total_amount !== null) {
335					const maxAmount = parseFloat(filterAmountMax);
336					if (!isNaN(maxAmount) && r.total_amount > maxAmount) return false;
337				}
338	
339				return true;
340			});
341		}
