452		// #{#blk3a} #{#blk3b} Execute bulk delete with optimistic update
453		async function executeBulkDelete(): Promise<void> {
454			isDeleting = true;
455			showDeleteConfirm = false;
456			errorMessage = null;
457			successMessage = null;
458	
459			// Optimistic update - remove from UI immediately
460			const idsToDelete = Array.from(selectedReceiptIds);
461			const originalReceipts = [...allReceipts];
462	
463			// #{#blk3b} Optimistic UI update
464			allReceipts = allReceipts.filter((r) => !selectedReceiptIds.has(r.id));
465	
466			try {
