785		/**
786		 * Show toast notification
787		 * #{#exp3b} Criterion 3, 4: Success/error feedback
788		 */
789		function showToast(message: string, type: 'success' | 'error') {
790			successMessage = message;
791			setTimeout(
792				() => {
793					successMessage = null;
794				},
795				type === 'success' ? 3000 : 5000
796			);
797		}
