1	<script lang="ts">
2		/**
3		 * Receipt Image Viewer Component
4		 *
5		 * Provides zoom and pan capabilities for receipt images in a floating modal.
6		 * Implements specifications #{#zom1a} through #{#zom5b} from
7		 * specs/specifications/receipt-image-zoom-pan.md
8		 *
9		 * Zoom anchors to cursor position (mouse wheel, pinch midpoint, double-tap).
10		 * Scrollable container replaces manual pan — native scrollbars + drag-to-scroll.
11		 *
12		 * @component
13		 */
14	
15		// Props — #{#pdf1a} added isPdf for PDF detection
16		interface Props {
17			imageUrl: string;
18			altText?: string;
19			show?: boolean;
20			isPdf?: boolean;
21			onclose?: () => void;
22		}
23	
24		let {
25			imageUrl,
26			altText = 'Receipt image',
27			show = false,
28			isPdf = false,
29			onclose
30		}: Props = $props();
31	
32		// Zoom state - #{#zom1a}
33		let zoom = $state(100);
34	
35		// Drag-to-scroll state - #{#zom2a}
36		let isDragging = $state(false);
37		let dragStartX = $state(0);
38		let dragStartY = $state(0);
39		let scrollStartX = $state(0);
40		let scrollStartY = $state(0);
41	
42		// Touch gesture state - #{#zom3a}
43		let touchStartDistance = $state(0);
44		let touchStartZoom = $state(100);
45		let lastTapTime = $state(0);
46	
47		// Image base dimensions (fit-to-viewport at 100%)
48		let baseWidth = $state(0);
49		let baseHeight = $state(0);
50	
51		// Loading state - #{#zom4b}
52		let isLoading = $state(false);
53	
54		// Refs
55		let scrollContainer: HTMLDivElement | undefined = $state(undefined);
56	
57		// Constants
58		const MIN_ZOOM = 100;
59		const MAX_ZOOM = 400;
60		const ZOOM_STEP = 50;
61		const PAN_STEP = 50;
62		const DOUBLE_TAP_DELAY = 300; // ms
63	
64		// Pending scroll adjustment for zoom-to-cursor
65		let rafId = 0;
66	
67		// Computed scaled dimensions
68		let scaledWidth = $derived((baseWidth * zoom) / 100);
69		let scaledHeight = $derived((baseHeight * zoom) / 100);
70	
71		/**
72		 * Capture base dimensions on image load — the size the image
73		 * occupies at 100% zoom, fit within the viewport constraints.
74		 */
75		function handleImageLoad(e: Event) {
76			const img = e.target as HTMLImageElement;
77			const natW = img.naturalWidth;
78			const natH = img.naturalHeight;
79			const maxW = window.innerWidth * 0.9;
80			const maxH = window.innerHeight * 0.8;
81			const scale = Math.min(maxW / natW, maxH / natH, 1);
82			baseWidth = natW * scale;
83			baseHeight = natH * scale;
84		}
85	
86		/**
87		 * #{#zom1a} Zoom to a specific level, optionally anchored at a cursor position.
88		 * The point under the cursor stays fixed on screen after zoom.
89		 */
90		function zoomTo(newZoom: number, cursorX?: number, cursorY?: number) {
91			const container = scrollContainer;
92			newZoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, newZoom));
93	
94			if (!container || baseWidth === 0) {
95				zoom = newZoom;
96				return;
97			}
98	
99			const oldZoom = zoom;
100			if (newZoom === oldZoom) return;
101	
102			const rect = container.getBoundingClientRect();
103			// Default to center of viewport if no cursor position given
104			const cx = cursorX !== undefined ? cursorX - rect.left : rect.width / 2;
105			const cy = cursorY !== undefined ? cursorY - rect.top : rect.height / 2;
106	
107			// Point in base-image coordinates under the cursor
108			const imageX = (container.scrollLeft + cx) / (oldZoom / 100);
109			const imageY = (container.scrollTop + cy) / (oldZoom / 100);
110	
111			zoom = newZoom;
112	
113			// After Svelte updates the DOM (image resizes), adjust scroll so the
114			// same image point remains under the cursor.
115			const targetScrollLeft = imageX * (newZoom / 100) - cx;
116			const targetScrollTop = imageY * (newZoom / 100) - cy;
117			cancelAnimationFrame(rafId);
118			rafId = requestAnimationFrame(() => {
119				if (container) {
120					container.scrollLeft = targetScrollLeft;
121					container.scrollTop = targetScrollTop;
122				}
123			});
124		}
125	
126		/**
127		 * #{#zom1a} Zoom in by one step (snaps to 50% increments)
128		 */
129		function zoomIn(cursorX?: number, cursorY?: number) {
130			zoomTo(Math.ceil((zoom + 1) / ZOOM_STEP) * ZOOM_STEP, cursorX, cursorY);
131		}
132	
133		/**
134		 * #{#zom1a} Zoom out by one step (snaps to 50% increments)
135		 */
136		function zoomOut(cursorX?: number, cursorY?: number) {
137			zoomTo(Math.floor((zoom - 1) / ZOOM_STEP) * ZOOM_STEP, cursorX, cursorY);
138		}
139	
140		/**
141		 * #{#zom1a} Reset zoom to 100% and scroll to origin
142		 */
143		function resetZoom() {
144			zoom = MIN_ZOOM;
145			if (scrollContainer) {
146				scrollContainer.scrollLeft = 0;
147				scrollContainer.scrollTop = 0;
148			}
149		}
150	
151		/**
152		 * #{#zom1b} #{#pdf1c} Handle mouse wheel zoom — disabled for PDFs.
153		 * Zooms toward the cursor position.
154		 */
155		function handleWheel(e: WheelEvent) {
156			if (isPdf) return; // #{#pdf1c} Let browser PDF viewer handle scroll
157			e.preventDefault();
158			if (e.deltaY < 0) {
159				zoomIn(e.clientX, e.clientY);
160			} else {
161				zoomOut(e.clientX, e.clientY);
162			}
163		}
164	
165		/**
